import { HumanMessage, ToolMessage } from "@langchain/core/messages"
import { createMiddleware } from "langchain"

/** Supplied only by the local Bot host, never inferred from user text or thread metadata. */
export interface BotTurnContext {
  event: "user_request" | "introduction" | "task_result" | "task_result_review"
  text: string
}

/** Attach once to this new input so checkpoints retain it without changing earlier messages. */
export function appendBotTurnContext(
  message: HumanMessage | undefined,
  context: BotTurnContext | undefined
): HumanMessage | undefined {
  if (!message || !context) return message
  const contextText = `\n\n<bot_runtime_context event="${context.event}">\n${context.text}\n</bot_runtime_context>`
  return new HumanMessage({
    ...message,
    content:
      typeof message.content === "string"
        ? message.content + contextText
        : [...message.content, { type: "text", text: contextText }],
    additional_kwargs: {
      ...message.additional_kwargs,
      // Existing transcript projection also used by skill and coordinator context.
      cmb_coordinator_augmented_user_message: true,
      cmb_visible_user_message:
        message.additional_kwargs.cmb_visible_user_message ?? message.content
    }
  })
}

/** Keep schemas stable; automatic result events cannot execute even if a provider ignores none. */
export function createBotResultReportMiddleware() {
  return createMiddleware({
    name: "botResultReport",
    wrapModelCall: (request, handler) => handler({ ...request, toolChoice: "none" }),
    wrapToolCall: (request) =>
      new ToolMessage({
        name: request.toolCall.name,
        tool_call_id: request.toolCall.id!,
        status: "error",
        content:
          "This task_result event cannot invoke tools. The call did not execute. Report only the supplied result, host status and receipts; do not retry or start work."
      })
  })
}

import { AIMessage, ToolMessage } from "@langchain/core/messages"
import { createMiddleware } from "langchain"
import type { BotTask } from "../../shared/bots/contracts"
import { parseSkillUseBlock } from "./skill-lifecycle/marker"

export const BOT_SKILL_DISPATCH_TOOL = "bot_skill_dispatch"
export interface BotSkillDispatch {
  name: string
  path: string
  block: string
}

/** Only a local main-Bot composer selection. Task, project and remote text keep their existing behavior. */
export function selectedMainBotSkill(task: BotTask): BotSkillDispatch | undefined {
  if (task.workId || task.mockSource || task.origin.kind !== "user") return
  if (task.origin.explicitSkill) return { ...task.origin.explicitSkill, block: "" }
  const selected = parseSkillUseBlock(task.message)
  return selected ? { name: selected.skillName, path: selected.skillPath, block: selected.block } : undefined
}

/** Preserve the stored/visible source; the dispatcher must not receive the executor's read-SKILL instruction. */
export function botSkillDispatchInput(input: string, selection: BotSkillDispatch): string {
  return input.replace(selection.block, "").trimEnd() +
    `\n\n<bot_skill_dispatch>\nThe user explicitly selected skill ${JSON.stringify(selection.name)}. ` +
    "Call bot_skill_dispatch now, with arguments only and no preliminary reply. Choose the destination, not whether to delegate. " +
    "Reuse the existing workId for a revision/continuation (or workQuery if its ID is absent); otherwise supply a short title. " +
    "Honor an explicitly designated directory or project; omit workspace for the default. " +
    "Do not read the skill or business files, run commands, plan the implementation or repeat the original request in the goal. " +
    "The host supplies the original request and activates the selected skill in the task. " +
    "After successful acceptance the host acknowledges once and ends this turn. If dispatch fails, explain the actual blocker briefly; never claim it started.\n</bot_skill_dispatch>"
}

/** Stable schemas, forced destination call, and a host gate before hooks or filesystem access. */
export function createBotSkillDispatchMiddleware() {
  let attempted = false
  return createMiddleware({
    name: "botSkillDispatch",
    wrapModelCall: async (request, handler) => {
      const selecting = !attempted
      const result = await handler({
        ...request,
        toolChoice: selecting ? { type: "function", function: { name: BOT_SKILL_DISPATCH_TOOL } } : "none"
      })
      if (!selecting) return result
      if (!AIMessage.isInstance(result) || result.tool_calls?.length !== 1 ||
          result.tool_calls[0].name !== BOT_SKILL_DISPATCH_TOOL)
        throw new Error("技能任务尚未启动：模型未返回有效的交办请求，请重试。")
      // The short routing model does not stream. Acknowledgement belongs to the
      // accepted host receipt, never to unverified prose accompanying arguments.
      return new AIMessage({ ...result, content: "" })
    },
    wrapToolCall: (request, handler) => {
      if (attempted || request.toolCall.name !== BOT_SKILL_DISPATCH_TOOL) {
        attempted = true
        return new ToolMessage({
          name: request.toolCall.name, tool_call_id: request.toolCall.id!, status: "error",
          content: "The selected-skill dispatch did not execute this call. Only one bot_skill_dispatch call is allowed in this main turn. Explain the actual blocker; do not perform the work here or claim acceptance without its receipt."
        })
      }
      attempted = true
      return handler(request)
    }
  })
}

import { createMiddleware } from "langchain"
import { ToolMessage } from "@langchain/core/messages"
import { BOT_CONTINUATION_KIND } from "../../shared/bots/turn-feedback"
import { acceptedBotDispatch } from "./bot-dispatch-feedback"

/** Per physical main-chat turn. Never inherited by a worker or persisted as a user preference. */
export interface ForegroundWorkBudget {
  beforeTool(name: string, args: unknown): string | undefined
  afterTool(name: string, result: unknown, args?: unknown): void
  checkFinal(): string | undefined
  yieldCommand(): void
}

const COORDINATION = new Set([
  "request_user_input",
  "bot_request_browser_help",
  "write_todos",
  "bot_work_create",
  "bot_skill_dispatch",
  "bot_work_send",
  "bot_work_continue",
  "bot_work_complete",
  "bot_work_list",
  "bot_work_read",
  "bot_work_search",
  "bot_work_projects",
  "bot_feature_list",
  "bot_feature_read",
  "bot_feature_update",
  "bot_send_message",
  "bot_list_groups",
  "bot_memory_search",
  "bot_memory_list",
  "bot_memory_get",
  "bot_remember",
  "bot_forget",
  "bot_update_profile",
  "bot_update_teammate",
  "bot_create_teammate",
  "bot_react_to_message",
  "bot_schedule",
  "bot_list_peers",
  "bot_delegate"
])
const NOTICE =
  "Foreground execution budget reached. This tool has NOT run. Keep the main chat available: hand the remaining assignment to bot_work_create, or continue its existing task/Feature. Include the user's goal and constraints, selected workspace, completed findings and exact command receipts; do not repeat completed actions or restart an accepted background command. Use finishTurn: true on the final dispatch batch. Keep the same assistant voice; do not mention budgets, internal errors or handing the user to another agent. If already acknowledged, do not add another acknowledgement. Do not poll or work around this boundary with another tool."

export function createForegroundWorkBudget(options: {
  yieldCommand(): void
  now?: () => number
  maxOperations?: number
  maxDurationMs?: number
}): ForegroundWorkBudget {
  const now = options.now ?? Date.now
  let started: number | undefined
  let operations = 0
  let handoffRequired = false
  let handedOff = false
  return {
    beforeTool(name, args) {
      if (
        COORDINATION.has(name) ||
        name.startsWith("bot_schedule_") ||
        (name === "bot_browser" && (args as { action?: string } | null)?.action === "request_help")
      )
        return
      // A synchronous child/workflow blocks the caller for its entire lifetime.
      // Persistent work is the asynchronous executor available to a main Bot.
      const exhausted =
        name === "task" ||
        name === "workflow" ||
        operations >= (options.maxOperations ?? 4) ||
        (started !== undefined && now() - started >= (options.maxDurationMs ?? 30_000))
      if (handoffRequired || exhausted) {
        if (!handoffRequired) handedOff = false
        handoffRequired = true
        return NOTICE
      }
      started ??= now()
      operations++
      return undefined
    },
    afterTool(name, result, args) {
      if (handoffRequired && acceptedBotDispatch(name, args, result)) handedOff = true
    },
    checkFinal: () => (handoffRequired && !handedOff ? NOTICE : undefined),
    yieldCommand: options.yieldCommand
  }
}

/** Runs before workspace locks and hooks. Rejected operations have no side effects. */
export function createForegroundWorkBudgetMiddleware(budget: ForegroundWorkBudget) {
  return createMiddleware({
    name: "foregroundWorkBudget",
    wrapToolCall: async (request, handler) => {
      const call = request.toolCall
      const notice = budget.beforeTool(call.name, call.args)
      if (notice)
        return new ToolMessage({
          name: call.name,
          tool_call_id: call.id!,
          status: "success",
          content: JSON.stringify({
            kind: BOT_CONTINUATION_KIND, version: 1, reason: "foreground_budget",
            executed: false, instruction: notice
          })
        })
      // Transfer the very same process through the sandbox's durable command
      // lifecycle. This neither kills it nor launches a replacement command.
      const timer =
        call.name === "execute" ? setInterval(() => budget.yieldCommand(), 10_000) : undefined
      try {
        const result = await handler(request)
        budget.afterTool(call.name, result, call.args)
        return result
      } finally {
        clearInterval(timer)
      }
    }
  })
}

import { AIMessage, ToolMessage, type BaseMessage } from "@langchain/core/messages"
import { createMiddleware } from "langchain"
import { randomUUID } from "node:crypto"
import type { BotDispatchFeedback } from "../../shared/bots/turn-feedback"
import { currentBotReplyState } from "./opening-reply-reminder"
import { BOT_SKILL_DISPATCH_TOOL } from "./bot-skill-dispatch"

const record = (value: unknown): value is Record<string, unknown> =>
  !!value && typeof value === "object" && !Array.isArray(value)
const nonempty = (value: unknown): value is string => typeof value === "string" && !!value.trim()

function readDispatchReceipt(name: string, result: unknown): Record<string, unknown> | undefined {
  const message = record(result) ? result : undefined
  if (message?.status === "error" || message?.is_error) return
  try {
    const value = JSON.parse(typeof result === "string" ? result : String(message?.content ?? ""))
    if (value?.kind === "bot-work-receipt" && value.operation === name && record(value.receipt))
      return value.receipt
  } catch {
    /* Not a native successful receipt. */
  }
  return undefined
}

/** Use the accepted task's origin, including name lookups and replayed receipts. */
function skillDispatchAcknowledgement(result: unknown): string {
  const receipt = readDispatchReceipt(BOT_SKILL_DISPATCH_TOOL, result)
  const origin = record(receipt?.task) ? receipt.task.origin : undefined
  if (record(origin) && origin.kind === "work") {
    if (origin.dispatch === "create")
      return "已新建任务，我会按所选技能处理，结果发回这里。"
    if (origin.dispatch === "follow_up")
      return "我会在原任务中继续处理，结果发回这里。"
  }
  // Legacy receipts without an origin cannot prove whether this is a new task.
  return "我会按所选技能处理，结果发回这里。"
}

/** Native receipts only. A reopened business task or a starting/failed Feature is not accepted execution. */
export function acceptedBotDispatch(name: string, args: unknown, result: unknown): boolean {
  const receipt = readDispatchReceipt(name, result)
  if (!receipt) return false
  try {
    const acceptedTask = (task: unknown) =>
      record(task) &&
      nonempty(task.id) &&
      nonempty(task.workId) &&
      nonempty(task.threadId) &&
      typeof task.state === "string" &&
      ["queued", "running", "waiting_user", "completed"].includes(task.state)
    if (name === "bot_work_create" || name === BOT_SKILL_DISPATCH_TOOL)
      return (
        acceptedTask(receipt.task) &&
        record(receipt.task) &&
        record(receipt.work) &&
        nonempty(receipt.work.id) &&
        !(name === BOT_SKILL_DISPATCH_TOOL && record(args) && args.workId && args.workId !== receipt.work.id) &&
        receipt.task.workId === receipt.work.id &&
        receipt.task.threadId === receipt.work.threadId &&
        receipt.task.botId === receipt.work.botId
      )
    if (name === "bot_work_send")
      return acceptedTask(receipt) && record(args) && receipt.workId === args.workId
    if (
      name === "bot_feature_update" &&
      record(args) &&
      typeof args.action === "string" &&
      ["session", "continue", "manage"].includes(args.action)
    ) {
      const operation = receipt.operation
      return (
        record(operation) &&
        nonempty(operation.id) &&
        operation.action === args.action &&
        typeof operation.state === "string" &&
        ["active", "finished"].includes(operation.state) &&
        !operation.error &&
        nonempty(args.action === "manage" ? operation.runId : operation.threadId)
      )
    }
  } catch {
    /* Not a native successful receipt. */
  }
  return false
}

/** Bounded by the latest visible request; a new steer or internal result always needs a fresh model turn. */
export function botDispatchFeedback(
  messages: readonly BaseMessage[]
): BotDispatchFeedback | undefined {
  let callIndex = messages.length - 1
  const results = new Map<string, ToolMessage>()
  while (callIndex >= 0 && ToolMessage.isInstance(messages[callIndex])) {
    const message = messages[callIndex] as ToolMessage
    if (results.has(message.tool_call_id)) return undefined
    results.set(message.tool_call_id, message)
    callIndex--
  }
  const assistant = messages[callIndex]
  if (!AIMessage.isInstance(assistant) || !assistant.tool_calls?.length) return
  const calls = assistant.tool_calls
  // The model explicitly closes its dispatch batch. Without this flag it may
  // still owe another destination, an immediate answer or a clarification.
  if (!calls.some((call) => call.args.finishTurn === true || call.name === BOT_SKILL_DISPATCH_TOOL) || results.size !== calls.length) return
  if (
    !calls.every(
      (call) => call.id && acceptedBotDispatch(call.name, call.args, results.get(call.id))
    )
  )
    return
  const state = currentBotReplyState(messages)
  if (!state?.requestMessageId || state.internalInput) return undefined
  const skillCall = calls.find(call => call.name === BOT_SKILL_DISPATCH_TOOL)
  return {
    requestMessageId: state.requestMessageId,
    hadOpening: !!state.opening,
    ...(state.followup ? { followup: state.followup } : {}),
    acknowledgement: state.opening || (skillCall
      ? skillDispatchAcknowledgement(results.get(skillCall.id!)) : "我会继续处理，结果会发回这里。")
  }
}

/** After the steer queue, before the next model call. No synthetic hidden assistant turn. */
export function createBotDispatchFeedbackMiddleware(
  onFeedback: (feedback: BotDispatchFeedback | undefined) => void
) {
  return createMiddleware({
    name: "botDispatchFeedback",
    beforeModel: {
      canJumpTo: ["end"],
      hook: (state) => {
        const feedback = botDispatchFeedback(state.messages)
        onFeedback(feedback)
        if (!feedback) return undefined
        return {
          ...(!feedback.hadOpening
            ? {
                messages: [
                  new AIMessage({
                    id: `bot-dispatch-${randomUUID()}`,
                    content: feedback.acknowledgement,
                    response_metadata: { finish_reason: "stop" }
                  })
                ]
              }
            : {}),
          jumpTo: "end" as const
        }
      }
    }
  })
}

import { AIMessage, HumanMessage, type BaseMessage } from "@langchain/core/messages"
import { createMiddleware } from "langchain"
import {
  isInternalNotificationMessage,
  isVisibleTranscriptMessage
} from "../../shared/checkpoint-transcript"
import { splitBotInlineReasoning } from "../../shared/bots/inline-reasoning"
import { getHookAgentIdFromRequest } from "../hooks/execution-context"
import { extractVisibleText } from "./turn-completion-integrity"

export const OPENING_REPLY_REMINDER =
  "You have used tools for the current user message without a visible reply. Briefly tell the user what you are doing or what you actually found, using normal assistant text. Do not expose private reasoning or invent progress. If work remains, include the next needed tool call in the same response so execution continues; this update is not task completion. If the work is already done, give the actual result directly instead of an extra acknowledgement."

export const ACKNOWLEDGED_REPLY_REMINDER =
  "The current user request already has a visible acknowledgement. Continue the next action without another opening or handoff announcement. Reading a skill, deciding to delegate, or receiving a dispatch receipt is not a new user-facing update; do not summarize the skill's workflow. If dispatch now covers all remaining work, call it with finishTurn: true and no assistant text. Still deliver any new actual answer, important finding, needed decision or genuine failure. Do not omit substantive results."

/** One request-scoped view shared by the opening nudge and accepted-dispatch completion. */
export function currentBotReplyState(messages: readonly BaseMessage[]):
  | {
      requestMessageId?: string
      opening: string
      followup: string
      toolCalls: number
      internalInput: boolean
    }
  | undefined {
  let toolCalls = 0, internalInput = false
  const replies: string[] = []
  for (let index = messages.length - 1; index >= 0; index--) {
    const message = messages[index]
    if (isInternalNotificationMessage(message)) {
      internalInput = true
      continue
    }
    if (HumanMessage.isInstance(message)) {
      if (!isVisibleTranscriptMessage("user", message.content)) {
        internalInput = true
        continue
      }
      return {
        requestMessageId: message.id,
        opening: replies.at(-1) ?? "",
        followup: replies.slice(0, -1).reverse().join("\n\n"),
        toolCalls,
        internalInput
      }
    }
    if (!AIMessage.isInstance(message)) continue
    const text = splitBotInlineReasoning(extractVisibleText(message.content)).body.trim()
    if (text) replies.push(text)
    toolCalls += message.tool_calls?.length ?? 0
  }
  // Compaction may remove the boundary. Never infer a new request from old tools.
  return undefined
}

/** Opt-in main-turn nudge, never a tool gate, extra model call or persisted chat message. */
export function createOpeningReplyReminderMiddleware(): ReturnType<typeof createMiddleware> {
  return createMiddleware({
    name: "openingReplyReminder",
    wrapModelCall: (request, handler) => {
      if (getHookAgentIdFromRequest(request)) return handler(request)
      const state = currentBotReplyState(request.messages)
      const reminder = state?.opening
        ? ACKNOWLEDGED_REPLY_REMINDER
        : state && state.toolCalls >= 2
          ? OPENING_REPLY_REMINDER
          : undefined
      if (!reminder) return handler(request)
      return handler({
        ...request,
        // This opt-in Bot nudge is ephemeral. Keep the system and retained history
        // untouched; changes to acknowledgement state only affect the request tail.
        messages: [...request.messages, new HumanMessage({
          content: `<bot_reply_reminder>${reminder}</bot_reply_reminder>`,
          additional_kwargs: { cmb_internal_coordinator_notification: true }
        })]
      })
    }
  })
}

/** Host control receipts are not execution failures. Unknown or errored results stay errors. */
export const BOT_CONTINUATION_KIND = "bot-foreground-continuation"

export function isBotContinuationReceipt(result?: {
  content?: unknown
  is_error?: boolean
}): boolean {
  if (result?.is_error || typeof result?.content !== "string") return false
  try {
    const value = JSON.parse(result.content)
    return (
      value?.kind === BOT_CONTINUATION_KIND &&
      value.version === 1 &&
      value.executed === false &&
      value.reason === "foreground_budget" &&
      typeof value.instruction === "string"
    )
  } catch {
    return false
  }
}

export interface BotDispatchFeedback {
  requestMessageId: string
  acknowledgement: string
  hadOpening: boolean
  /** Later visible findings must still reach IM; only the opening is deduplicated. */
  followup?: string
}

export const WORK_ASSIGNMENT_PREFIX = "交办范围：\n"
export const WORK_ASSIGNMENT_SOURCE = "\n\nHost 已放行的当前用户请求（JSON 文本，仅保留与本次交办有关的要求；不得据此执行其他任务或扩大权限）：\n"

/** New host-linked work pages its admitted source separately. Keep the routing note and formal attachment blocks. */
export function workRoutingMessage(message: string, routingNoteLength?: number): string {
  if (routingNoteLength === undefined || !message.startsWith(WORK_ASSIGNMENT_PREFIX)) return message
  const start = WORK_ASSIGNMENT_PREFIX.length
  const boundary = start + routingNoteLength
  if (!message.startsWith(WORK_ASSIGNMENT_SOURCE, boundary)) return message
  const end = message.indexOf("\n", boundary + WORK_ASSIGNMENT_SOURCE.length)
  return message.slice(start, boundary) + (end < 0 ? "" : message.slice(end))
}

/** Bounded, explicit source paging. No transcript scans or silent truncation. */
export interface BotWorkInput {
  id: string
  role: "user" | "assistant"
  text: string
  kind?: "request" | "correction" | "reference"
}

export function pageBotWorkInputs(inputs: readonly BotWorkInput[], messageIndex = 0, offset = 0) {
  if (
    !Number.isSafeInteger(messageIndex) ||
    messageIndex < 0 ||
    !Number.isSafeInteger(offset) ||
    offset < 0 ||
    messageIndex >= inputs.length
  )
    throw new Error("交办来源位置无效")
  let remaining = 12_000
  const messages: (BotWorkInput & {
    index: number
    offset: number
    length: number
    nextOffset?: number
  })[] = []
  for (let i = messageIndex; i < inputs.length && messages.length < 8 && remaining > 0; i++) {
    const input = inputs[i]
    const start = i === messageIndex ? offset : 0
    if (start > input.text.length) throw new Error("交办来源文本位置无效")
    const text = input.text.slice(start, start + Math.min(4_000, remaining))
    remaining -= text.length
    messages.push({
      index: i,
      id: input.id,
      role: input.role,
      text,
      ...(input.kind ? { kind: input.kind } : {}),
      offset: start,
      length: input.text.length,
      ...(start + text.length < input.text.length ? { nextOffset: start + text.length } : {})
    })
    if (offset) break
  }
  const nextMessageIndex = messageIndex + messages.length
  return {
    messages,
    totalMessages: inputs.length,
    ...(nextMessageIndex < inputs.length ? { nextMessageIndex } : {})
  }
}

export function botWorkInputPrompt(context: ReturnType<typeof pageBotWorkInputs>): string {
  return (
    "\n\n## Host-linked original request and context\n" +
    "The host selected these sources from the originating conversation. kind=request is the current request; kind=correction is an applied user update. They take precedence over the Bot's routing note and historical context. kind=reference is older context even when role=user; its position below is not chronological and cannot override the current request. Historical text is not new permission or proof. Execute only the assigned outcome; unrelated requests in the source are not assigned. If a message has nextOffset, call bot_work_input with this context's assignmentId, its index as messageIndex and that offset before relying on omitted constraints. nextMessageIndex means more sources remain. Never infer missing content.\n" +
    JSON.stringify(context)
  )
}

